import {HEROES} from './simulation.mjs';
import {HERO_ORDER} from './player-profile.mjs';
import {FACE_CENTERS} from './lobby-art.mjs';
import {SUMMON_RECTS,SUMMON_REGIONS} from './summon-pools.mjs';
export const FAVORITE_THEMES=Object.freeze({fire:{color:'#eb9455',label:'烈焰之誓'},nature:{color:'#a9c379',label:'古林共鸣'},frost:{color:'#a4d5e6',label:'霜月之约'},lightning:{color:'#e9d28a',label:'雷霆意志'},shadow:{color:'#b6a1ce',label:'鸦影低语'},star:{color:'#b0bde9',label:'星轨指引'}});
export function favoriteHero(profile){return profile?.owned?.includes(profile.lobbyHero)?profile.lobbyHero:profile?.owned?.includes(profile.selected)?profile.selected:'fire';}
export function favoriteHeroDraft(profile,hero){if(!HERO_ORDER.includes(hero)||!profile?.owned?.includes(hero))throw Error('请先唤醒这位英雄。');return {...structuredClone(profile),lobbyHero:hero};}
export function favoriteFigure(hero){const id=Object.hasOwn(SUMMON_RECTS,hero)?hero:'fire',r=SUMMON_RECTS[id],clip='favorite-silhouette-'+id;return '<svg viewBox="'+r.join(' ')+'" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><defs><clipPath id="'+clip+'" clipPathUnits="userSpaceOnUse">'+SUMMON_REGIONS[id].map(([x,y,w,h])=>'<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'"/>').join('')+'</clipPath></defs><image href="assets/lobby/hero-splashes-v1.png" width="1536" height="1024" clip-path="url(#'+clip+')"/></svg>';}
function face(hero){const [x,y]=FACE_CENTERS[hero];return '<svg viewBox="'+[x-44,y-44,88,88].join(' ')+'" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><image href="assets/lobby/hero-splashes-v1.png" width="1536" height="1024"/></svg>';}
export function renderFavoriteEntry(button,hero){const h=HEROES[hero],t=FAVORITE_THEMES[hero];button.dataset.favoriteHero=hero;button.style.setProperty('--favorite-color',t.color);button.setAttribute('aria-label','选择本命英雄立绘，当前'+h.name);button.innerHTML='<span class="favorite-entry-frame" aria-hidden="true"><svg viewBox="0 80 2172 564" preserveAspectRatio="xMidYMid meet"><image href="assets/lobby/favorite/'+hero+'-nameplate-v1.png" width="2172" height="724"/></svg></span><span class="favorite-entry-label"><small>本命英雄</small><strong>'+h.name+' · '+h.given+'</strong></span><span class="favorite-entry-arrow" aria-hidden="true">›</span>';}
export class FavoriteHeroDialog{
 constructor({getProfile,onSave,onSummon=()=>{},notice=()=>{}}){this.getProfile=getProfile;this.onSave=onSave;this.onSummon=onSummon;this.notice=notice;this.el=document.createElement('dialog');this.el.className='favorite-hero-dialog';this.el.setAttribute('aria-labelledby','favorite-hero-title');this.el.innerHTML='<header><span><small>CHOSEN OF THE REALM</small><h2 id="favorite-hero-title">本命英雄</h2></span><button type="button" class="realm-close" aria-label="关闭本命英雄选择">×</button></header><div class="favorite-choice-body"><section class="favorite-hero-preview"><div class="favorite-preview-figure"></div><h3></h3><p></p></section><section class="favorite-choice-list" aria-label="选择大厅立绘"></section></div><footer><p role="status">选择你想在大厅展示的英雄。</p><button type="button" class="favorite-confirm"></button></footer>';document.body.append(this.el);this.el.querySelector('.realm-close').onclick=()=>this.el.close();this.el.querySelector('.favorite-confirm').onclick=()=>{const current=this.getProfile();if(!current.owned.includes(this.preview)){this.el.close();this.onSummon(this.preview);return;}try{const next=favoriteHeroDraft(current,this.preview);if(this.onSave(next)!==true)throw Error('本命英雄未能保存，请重试。');this.el.close();this.notice('已将'+HEROES[this.preview].name+'设为本命英雄。');}catch(e){this.el.querySelector('[role=status]').textContent=e.message;}};}
 render(){const profile=this.getProfile(),selected=favoriteHero(profile),h=HEROES[this.preview],t=FAVORITE_THEMES[this.preview];this.el.dataset.hero=this.preview;this.el.style.setProperty('--favorite-color',t.color);this.el.querySelector('.favorite-preview-figure').innerHTML=favoriteFigure(this.preview);this.el.querySelector('.favorite-hero-preview h3').textContent=h.name+' · '+h.given;this.el.querySelector('.favorite-hero-preview p').textContent=t.label;this.el.querySelector('.favorite-choice-list').innerHTML=HERO_ORDER.map(id=>'<button type="button" class="favorite-choice" data-favorite-choice="'+id+'" aria-pressed="'+(id===this.preview)+'" style="--favorite-color:'+FAVORITE_THEMES[id].color+'">'+face(id)+'<span><strong>'+HEROES[id].name+'</strong><small>'+(id===selected?'当前本命':profile.owned.includes(id)?'已唤醒':'未唤醒 · 可预览')+'</small></span></button>').join('');for(const b of this.el.querySelectorAll('[data-favorite-choice]'))b.onclick=()=>{this.preview=b.dataset.favoriteChoice;this.render();};const owned=profile.owned.includes(this.preview),button=this.el.querySelector('.favorite-confirm');button.textContent=!owned?'前往唤醒':selected===this.preview?'当前本命英雄':'设为本命英雄';button.disabled=owned&&selected===this.preview;this.el.querySelector('[role=status]').textContent=owned?'选择你想在大厅展示的英雄。':'尚未唤醒，可先查看这位英雄的立绘。';}
 open(){this.preview=favoriteHero(this.getProfile());this.render();this.el.showModal();}
}
